import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { useAudio } from '../contexts/AudioContext';
import '../styles/pages/LandingPage.css';

const LandingPage: React.FC = () => {
  const { isPlaying, playLandingMusic } = useAudio();
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const hasTriedPlayRef = useRef(false);
  
  // Intentar reproducir música automáticamente cuando se carga el componente
  useEffect(() => {
    if (!hasTriedPlayRef.current) {
      hasTriedPlayRef.current = true;
      
      const attemptPlay = async () => {
        try {
          // Intento directo a través del contexto de audio
          await playLandingMusic();
        } catch (error) {
          console.error("Error al iniciar música automáticamente:", error);
          
          // Intento con el elemento de audio HTML
          if (audioRef.current) {
            try {
              // Intento con volumen 0 para eludir restricciones
              audioRef.current.volume = 0;
              await audioRef.current.play();
              
              // Subir volumen gradualmente
              const fadeIn = () => {
                if (audioRef.current) {
                  const newVol = Math.min(audioRef.current.volume + 0.1, 0.5);
                  audioRef.current.volume = newVol;
                  
                  if (newVol < 0.5) {
                    setTimeout(fadeIn, 100);
                  }
                }
              };
              
              setTimeout(fadeIn, 500);
            } catch (htmlErr) {
              console.error("Imposible reproducir audio automáticamente:", htmlErr);
            }
          }
        }
      };
      
      attemptPlay();
      
      // Programar múltiples intentos
      const timers: number[] = [];
      [500, 1000, 2000, 3000].forEach(delay => {
        const timer = window.setTimeout(() => {
          if (!isPlaying) {
            console.log(`Intento programado después de ${delay}ms`);
            playLandingMusic().catch(e => console.log(`Error en intento ${delay}ms:`, e));
          }
        }, delay);
        timers.push(timer);
      });
      
      return () => {
        timers.forEach(t => window.clearTimeout(t));
      };
    }
  }, [playLandingMusic, isPlaying]);

  // Verificar archivos de audio
  useEffect(() => {
    const checkAudioFiles = async () => {
      try {
        const landingResponse = await fetch('/assets/audio/landing-theme.mp3');
        if (!landingResponse.ok) {
          setErrorMessage(`No se encontró el archivo de audio. Estado: ${landingResponse.status}`);
        }
      } catch (error) {
        setErrorMessage("Error al verificar archivos de audio: " + (error instanceof Error ? error.message : "Error desconocido"));
      }
    };
    
    checkAudioFiles();
  }, []);

  return (
    <div className="landing-page">
      {errorMessage && (
        <div className="error-message">
          {errorMessage}
        </div>
      )}
      
      <div className="landing-content">
        <div className="title-container">
          <h1 className="game-title">Heroes&Hostias</h1>
        </div>
        
        <div className="buttons-container">
          <Link to="/login" className="landing-button login-button">
            <span className="button-text">Iniciar Sesión</span>
          </Link>
          
          <Link to="/register" className="landing-button register-button">
            <span className="button-text">Registrarse</span>
          </Link>
        </div>
      </div>
      
      <div className="version-footer">
        <span>v1.0.0 Beta</span>
      </div>
      
      {/* Elemento de audio para reproducción directa como fallback */}
      <audio 
        ref={audioRef}
        src="/assets/audio/landing-theme.mp3" 
        loop
        preload="auto"
        style={{ display: 'none' }}
      />
    </div>
  );
};

export default LandingPage;
